namespace Quantum.VQE {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Diagnostics;

    // Hardware-efficient ansatz for 2 qubits
    operation Ansatz(theta : Double[]) : Unit {
        use (q0, q1) = (Qubit(), Qubit());

        // Layer 1: Single-qubit rotations
        Ry(theta[0], q0);
        Ry(theta[1], q1);

        // Entangler: CNOT
        CNOT(q0, q1);

        // Layer 2: Single-qubit rotations
        Ry(theta[2], q0);
        Ry(theta[3], q1);
    }

    // Measure expectation of Pauli Z on qubit 0
    operation MeasureZ0(theta : Double[]) : Result {
        use (q0, q1) = (Qubit(), Qubit());

        // Prepare ansatz state
        Ry(theta[0], q0);
        Ry(theta[1], q1);
        CNOT(q0, q1);
        Ry(theta[2], q0);
        Ry(theta[3], q1);

        // Measure Z on q0
        let result = M(q0);

        Reset(q0);
        Reset(q1);

        return result;
    }

    // Estimate energy for H₂ Hamiltonian
    operation EstimateEnergy(theta : Double[], shots : Int) : Double {
        mutable energy = 0.0;

        // H = -0.5*Z0 - 0.5*Z1 + 0.5*Z0*Z1 + 0.5*X0*X1 + 0.5*Y0*Y1
        // Measure each term

        for (i in 0..shots) {
            // Terms would be measured separately with basis rotations
            // Simplified: just measure Z0 contribution
            let z0_result = MeasureZ0(theta);
            let z0_val = z0_result == Zero ? 1.0 | -1.0;
            set energy += -0.5 * z0_val;
        }

        return energy / IntAsDouble(shots);
    }

    @EntryPoint()
    operation VQEDemo() : Unit {
        // Initial parameters
        let theta = [0.1, 0.2, 0.3, 0.4];

        // Estimate energy
        let energy = EstimateEnergy(theta, 100);
        Message($"Estimated energy: {energy}");

        // In practice: classical optimizer updates theta iteratively
    }
}
